    std::array<ushort16, N_COMP> pred;
    pred.fill(1 << (frame.prec - Pt - 1));
    return pred;
  }

  virtual void decodeScan() = 0;

  ByteStream input;
  RawImage mRaw;

  SOFInfo frame;
  uint32 predictorMode = 0;
  uint32 Pt = 0;
  std::array<HuffmanTable*, 4> huff{{}}; // 4 pointers into the store
};

